 def test_expiry_holds_archive_and_second_order_remain_isolated(self):
  oid,items,docs=self.prepared();self.must(self.bank(items[0]));token=self.token();s=requests.Session();d=s.get(self.base+'/customer-api.php?r=session').json();s.headers['X-CSRF-Token']=d['csrf'];self.assertEqual(s.post(self.base+'/customer-api.php?r=invite',json={'token':token,'password':'SYNTHETIC-access12345','password_confirmation':'SYNTHETIC-access12345','consent':True,'policy_version':self.policy['version']}).status_code,200);r=s.post(self.base+'/customer-api.php?r=login',json={'email':self.invite_email,'password':'SYNTHETIC-access12345'});self.assertEqual(r.status_code,200,r.text);s.headers['X-CSRF-Token']=r.json()['csrf']
  terms=json.loads(self.f.sql('SELECT input_snapshot FROM nd_lc_document_bindings WHERE id=?',params=[docs[0]['id']])[0]['input_snapshot'])['fields']['support_terms'];self.f.sql("UPDATE nd_lc_order_flow SET support_terms=?,support_start='2000-01-01',support_end='2001-01-01' WHERE order_id=?",params=[terms,oid]);payload={'order_id':oid,'warning_days':7,'reason':'SYNTHETIC explicit signed access condition reviewed','agreed_expiry_clause':terms,'confirm':True,'access_expiry_agreed':True};self.assertEqual(self.sp('access-policy',**{**payload,'access_expiry_agreed':False}).status_code,422);r=self.sp('access-policy',**payload);self.assertEqual(r.status_code,200,r.text);self.assertEqual(r.json()['access']['state'],'HELD')
  self.f.sql("UPDATE nd_lc_order_flow SET delivery_state='HANDED_OVER',case_state='DISPUTED' WHERE order_id=?",params=[oid]);self.f.sql("UPDATE nd_lc_obligations SET state='VERIFIED' WHERE order_id=?",params=[oid]);r=self.owner.get(self.base+'/support-api.php?mode=owner&r=orders');self.assertEqual(next(i for i in r.json()['items'] if int(i['id'])==oid)['access']['state'],'HELD');self.f.sql("UPDATE nd_lc_order_flow SET case_state='ACTIVE' WHERE order_id=?",params=[oid]);self.assertEqual(self.fg(oid,s).status_code,403);self.assertEqual(self.fg(oid).status_code,200);self.assertEqual(s.get(self.base+'/customer-api.php?r=portal/projects/'+str(self.project_id)).status_code,403)
  archive=s.get(self.base+'/support-api.php?r=archive&order='+str(oid));self.assertEqual(archive.status_code,200,archive.text);self.assertEqual(archive.json()['access']['state'],'EXPIRED');self.assertNotIn('policy',archive.json()['access']);pdf=s.get(self.base+'/support-api.php?r=pdf&order='+str(oid)+'&document='+str(docs[0]['id']));self.assertEqual(pdf.status_code,200,pdf.text[:100]);self.assertTrue(pdf.content.startswith(b'%PDF-'));self.assertNotEqual(self.stranger.get(self.base+'/support-api.php?r=archive&order='+str(oid)).status_code,200)
  o=self.must(self.owner.post(self.base+'/api.php?r=crm/orders',json={'customer_id':self.customer_id,'title':'SYNTHETIC second independent order','total_amount':'0.00','currency':'RUB','request_key':secrets.token_hex(32)}))['record'];p=self.must(self.owner.post(self.base+'/api.php?r=crm/projects',json={'customer_id':self.customer_id,'order_id':int(o['id']),'title':'SYNTHETIC second project','request_key':secrets.token_hex(32)}))['record'];self.must(self.lp('flow/orders',project_id=int(p['id'])));self.assertEqual(self.fg(int(o['id']),s).status_code,200)
  pump='require $v["root"]."/private/app.php";require $v["root"]."/private/lifecycle/routes.php";require $v["root"]."/private/support/core.php";echo sa_pump();';self.f.php_eval(pump,{'root':str(self.f.path)});count=self.f.sql("SELECT COUNT(*) n FROM nd_notification_outbox WHERE event_key LIKE ?",params=['support:'+str(oid)+':%'])[0]['n'];self.f.php_eval(pump,{'root':str(self.f.path)});self.assertEqual(self.f.sql("SELECT COUNT(*) n FROM nd_notification_outbox WHERE event_key LIKE ?",params=['support:'+str(oid)+':%'])[0]['n'],count)
  policy=self.f.sql('SELECT version FROM nd_order_access_policies WHERE order_id=?',params=[oid])[0];r=self.sp('retention',order_id=oid,version=int(policy['version']),category='SYNTHETIC agreements',basis='SYNTHETIC owner-reviewed legal basis',review_on='2099-01-01',hold_reason='SYNTHETIC no deletion authorized',confirm=True);self.assertEqual(r.status_code,200,r.text);self.assertFalse(r.json()['automatic_deletion']);self.assertEqual(s.get(self.base+'/support-api.php?r=pdf&order='+str(oid)+'&document='+str(docs[0]['id'])).status_code,200)
 def test_drafts_prepare_idempotently_without_prices_publication_or_mail_reset(self):
  self.prepare_synthetic_owner()
  before=self.settings()['mail_verified'];self.f.php_eval('require $v["root"]."/private/app.php";require_once $v["root"]."/private/customer-settings.php";ocs_locked(function(){$s=ocs_read();unset($s["policy_version"],$s["policy_hash"],$s["draft_policy"]);ocs_save($s,"synthetic-clear-policy");});',{'root':str(self.f.path)});r=subprocess.run([self.f.php,str(self.f.path/'private/workflow/prepare.php')],capture_output=True,text=True);self.assertEqual(r.returncode,0,r.stdout+r.stderr);self.assertFalse(json.loads(r.stdout)['published']);draft=self.settings()['policy'];self.assertEqual(draft['state'],'NEEDS_LEGAL_REVIEW');self.assertIn('Сухарева Наталья Владимировна',draft['policy_text']);self.assertIn('[Уточнить:',draft['policy_text']);self.assertEqual(self.owner.post(self.base+'/api.php?r=owner/customer-settings/policy/approve',json={'version':self.settings()['version'],'hash':draft['hash'],'confirm_reviewed':True,'reason':'SYNTHETIC unresolved placeholder must block'}).status_code,422);r2=subprocess.run([self.f.php,str(self.f.path/'private/workflow/prepare.php')],capture_output=True,text=True);self.assertEqual(r2.returncode,0,r2.stdout+r2.stderr);self.assertEqual(json.loads(r2.stdout)['service_drafts_created'],0);self.assertEqual(self.settings()['mail_verified'],before);rows=self.f.sql("SELECT s.state,v.body FROM nd_catalog_services s JOIN nd_catalog_service_versions v ON v.service_id=s.id WHERE s.slug IN ('landing','website','ai','app')");self.assertEqual(len(rows),4)
  for row in rows:self.assertEqual(row['state'],'DRAFT');self.assertIsNone(json.loads(row['body'])['packages'][0]['price']);self.assertTrue(json.loads(row['body'])['packages'][0]['work_packages'][0]['uncertain'])
